// Generates src/renderer/lib/monaco.ts: every Monaco editor feature, none of the bundled languages.
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const src = fs.readFileSync(path.join(root, 'node_modules/monaco-editor/esm/vs/editor/editor.main.js'), 'utf8');
const lines = src.split('\n').filter((l) => /^import '/.test(l) && !/languages\//.test(l));
const out = [
  '// Generated by scripts/gen-monaco.mjs from monaco-editor/esm/vs/editor/editor.main.js.',
  '// All editor features, none of the bundled languages (JBeam is registered by the app).',
  ...lines.map((l) => l.replace(/^import '\.\.\//, "import 'monaco-editor/").replace(/^import '\.\//, "import 'monaco-editor/editor/")),
  "import * as monaco from 'monaco-editor/editor/editor.api.js';",
  "import EditorWorker from 'monaco-editor/editor/editor.worker.js?worker';",
  '',
  '(self as any).MonacoEnvironment = { getWorker: () => new EditorWorker() };',
  '',
  'export { monaco };',
  'export default monaco;',
  '',
];
fs.writeFileSync(path.join(root, 'src/renderer/lib/monaco.ts'), out.join('\n'));
console.log(lines.length, 'feature imports');
